53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const FIRST_INSURANCE_RATE = 0.1;
62	const CURSE_SURCHARGE_RATE = 0.5;
63	const HIGH_ENCHANTMENT_THRESHOLD = 5;
64	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
65	const PROCESSING_FEE = 5;
66	const LOYALTY_YEARS_THRESHOLD = 2;
67	const LOYALTY_DISCOUNT_RATE = 0.2;
68	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
69	const ALIKE_BLOCK_SIZE = 3;
70	const ALIKE_BLOCK_PREMIUM = 60;
71	
72	const countBy = <T>(items: T[], keyOf: (item: T) => string): Map<string, number> => {
73	  const counts = new Map<string, number>();
74	  for (const item of items) {
75	    const key = keyOf(item);
76	    counts.set(key, (counts.get(key) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	const countItemsByType = (items: QuoteItem[]): Map<string, number> =>
82	  countBy(items, (item) => item.type);
83	
84	const basePremiumForType = (type: string): number => {
85	  const basePremium = ITEM_BASE_PREMIUMS[type];
86	  if (basePremium === undefined) {
87	    throw new Error(`Unknown item type: ${type}`);
88	  }
89	  return basePremium;
90	};
91	
92	const premiumForAlikeGroup = (type: string, count: number): number => {
93	  const basePremium = basePremiumForType(type);
94	  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
95	  return formsExactlyOneBlock ? ALIKE_BLOCK_PREMIUM : count * basePremium;
96	};
97	
98	const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
99	  let total = 0;
100	  for (const [type, count] of countItemsByType(items)) {
101	    total += premiumForAlikeGroup(type, count);
102	  }
103	  return total;
104	};
105	
106	const itemSurcharge = (
107	  items: QuoteItem[],
108	  applies: (item: QuoteItem) => boolean,
109	  rate: number,
110	): number =>
111	  items.reduce(
112	    (sum, item) =>
113	      applies(item) ? sum + basePremiumForType(item.type) * rate : sum,
114	    0,
115	  );
116	
117	const calculateCurseSurcharge = (items: QuoteItem[]): number =>
118	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
119	
120	const calculateHighEnchantmentSurcharge = (items: QuoteItem[]): number =>
121	  itemSurcharge(
122	    items,
123	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
125	  );
126	
127	const calculateQuotePremium = (
128	  items: QuoteItem[],
129	  customer: Customer,
130	  isFollowUpContract: boolean,
131	): number => {
132	  const policyBasePremium = calculatePolicyBasePremium(items);
133	  const curseSurcharge = calculateCurseSurcharge(items);
134	  const highEnchantmentSurcharge = calculateHighEnchantmentSurcharge(items);
135	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
136	  const loyaltyDiscount =
137	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
138	      ? policyBasePremium * LOYALTY_DISCOUNT_RATE
139	      : 0;
140	  const followUpDiscount = isFollowUpContract
141	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
142	    : 0;
143	  return Math.ceil(
144	    policyBasePremium +
145	      curseSurcharge +
146	      highEnchantmentSurcharge +
147	      firstInsuranceSurcharge -
148	      loyaltyDiscount -
149	      followUpDiscount +
150	      PROCESSING_FEE,
151	  );
152	};
153	
154	const ITEM_INSURANCE_VALUES: Record<string, number> = {
155	  sword: 1000,
156	  amulet: 600,
157	  rune: 250,
158	};
159	const DEDUCTIBLE = 100;
160	const PAYOUT_CAP_MULTIPLIER = 2;
161	// Claim-side threshold — a separate business rule from the premium-side
162	// HIGH_ENCHANTMENT_THRESHOLD (5); do not merge them.
163	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
164	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
165	
166	const calculateInsuranceSum = (items: QuoteItem[]): number =>
167	  items.reduce((sum, item) => sum + ITEM_INSURANCE_VALUES[item.type], 0);
168	
169	const initialPayoutCap = (policy: QuoteStep): number =>
170	  calculateInsuranceSum(policy.items) * PAYOUT_CAP_MULTIPLIER;
171	
172	const reimbursementForDamage = (
173	  damage: Damage,
174	  insuredItems: QuoteItem[],
175	): number => {
176	  if (damage.amount < 0) {
177	    throw new Error(`Negative damage amount: ${damage.amount}`);
178	  }
179	  const damagedItem = insuredItems.find(
180	    (item) => item.type === damage.itemType,
181	  );
182	  if (damagedItem === undefined) {
183	    throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
184	  }
185	  const hasHighEnchantment =
186	    (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD;
187	  const reimbursedAmount = hasHighEnchantment
188	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
189	    : damage.amount;
190	  return reimbursedAmount - DEDUCTIBLE;
191	};
192	
193	const assertDamagesCoveredByPolicy = (
194	  damages: Damage[],
195	  insuredItems: QuoteItem[],
196	): void => {
197	  const insuredCounts = countItemsByType(insuredItems);
198	  const damageCounts = countBy(damages, (damage) => damage.itemType);
199	  for (const [type, damageCount] of damageCounts) {
200	    if (damageCount > (insuredCounts.get(type) ?? 0)) {
201	      throw new Error(`More damages than insured items of type: ${type}`);
202	    }
203	  }
204	};
205	
206	const processClaim = (
207	  claimStep: ClaimStep,
208	  policy: QuoteStep,
209	  remainingCapBefore: number,
210	): ClaimResult => {
211	  assertDamagesCoveredByPolicy(claimStep.incident.damages, policy.items);
212	  const totalReimbursed = claimStep.incident.damages.reduce(
213	    (sum, damage) => sum + reimbursementForDamage(damage, policy.items),
214	    0,
215	  );
216	  const payout = Math.min(Math.floor(totalReimbursed), remainingCapBefore);
217	  return { payout, remainingCap: remainingCapBefore - payout };
218	};
219	
220	export const runScenario = (scenario: Scenario): ScenarioResult => {
221	  const remainingCaps = new Map<number, number>();
222	  const results = scenario.steps.map((step, index): StepResult => {
223	    if (step.op === "claim") {
224	      const policy = scenario.steps[step.policy] as QuoteStep;
225	      const remainingCapBefore =
226	        remainingCaps.get(step.policy) ?? initialPayoutCap(policy);
227	      const result = processClaim(step, policy, remainingCapBefore);
228	      remainingCaps.set(step.policy, result.remainingCap);
229	      return result;
230	    }
231	    const isFollowUpContract = index > 0;
232	    return {
233	      premium: calculateQuotePremium(
234	        step.items,
235	        scenario.customer,
236	        isFollowUpContract,
237	      ),
238	    };
239	  });
240	  return { results };
241	};
